class LRUCache {
  #capacity;
  #map = new Map(); // Map은 삽입 순서를 기억한다
  constructor(capacity) {
    this.#capacity = capacity;
  }
  get(key) {
    if (!this.#map.has(key)) return -1;
    const value = this.#map.get(key);
    this.#map.delete(key);
    this.#map.set(key, value); // 맨 뒤로 다시 삽입 = '가장 최근'으로 갱신
    return value;
  }
  put(key, value) {
    if (this.#map.has(key)) this.#map.delete(key);
    else if (this.#map.size >= this.#capacity) {
      const oldest = this.#map.keys().next().value; // 맨 앞 = 가장 오래됨
      this.#map.delete(oldest);
    }
    this.#map.set(key, value);
  }
}

const cache = new LRUCache(2);
cache.put(1, 'a');
cache.put(2, 'b');
cache.get(1);       // 1을 사용 → 1이 '최근'으로 이동
cache.put(3, 'c');  // 용량 초과 → 가장 오래된 2를 제거
cache.get(2);
